        col_ranges.append((start, w))

    for r0, r1 in row_ranges:
        for j in range(len(col_ranges) - 1):
            c0, c1 = col_ranges[j]
            d0, d1 = col_ranges[j + 1]
            if c1 - c0 != d1 - d0:
