 "content": "def transform(grid):
    """Complete missing horizontal mirror copies in the same-color panel pair."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the full horizontal/vertical separator lines.
    sep_rows = [r for r in range(h)
                if grid[r][0] != 0 and all(v == grid[r][0] for v in grid[r])]
    sep_cols = [c for c in range(w)
                if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def ranges(n, separators):
        ans, start = [], 0
        for q in separators:
            if start < q:
                ans.append((start, q))
            start = q + 1
        if start < n:
            ans.append((start, n))
        return ans

    bands = ranges(h, sep_rows)
    panels = ranges(w, sep_cols)

    # Learn which adjacent panel pair belongs to each foreground color from
    # bands where both sides visibly contain horizontally reflected patterns.
    pair_counts = {}
    for r0, r1 in bands:
        for j in range(len(panels) - 1):
            c0, c1 = panels[j]
            d0, d1 = panels[j + 1]
            if c1 - c0 != d1 - d0 or r1 - r0 != r1 - r0:
                continue
            for color in range(1, 10):
                left = {(r-r0, c-c0) for r in range(r0, r1)
                        for c in range(c0, c1) if grid[r][c] == color}
                right = {(r-r0, c-d0) for r in range(r0, r1)
                         for c in range(d0, d1) if grid[r][c] == color}
                if left and right and right == {(dr, c1-c0-1-dc) for dr, dc in left}:
                    pair_counts.setdefault(color, {})[j] = pair_counts.setdefault(color, {}).get(j, 0) + 1

    pairs = {color: max(counts, key=counts.get) for color, counts in pair_counts.items()}
    for color, j in pairs.items():
        c0, c1 = panels[j]
        d0, d1 = panels[j+1]
        width = c1-c0
        if width != d1-d0:
            continue
        for r0, r1 in bands:
            left = [(r-r0, c-c0) for r in range(r0, r1)
                    for c in range(c0, c1) if grid[r][c] == color]
            right = [(r-r0, c-d0) for r in range(r0, r1)
                     for c in range(d0, d1) if grid[r][c] == color]
            if left and not right:
                for dr, dc in left:
                    out[r0+dr][d0+width-1-dc] = color
            elif right and not left:
                for dr, dc in right:
                    out[r0+dr][c0+width-1-dc] = color
    return out
